		? ctx.bin.trim()
		: (typeof envMap?.[DISCOVERY_ENV_VARS.muse] === "string" && envMap[DISCOVERY_ENV_VARS.muse].trim()
			? envMap[DISCOVERY_ENV_VARS.muse].trim()
