	if (!url) {
		throwLegError(
			"OPENCODE_NOT_CONFIGURED",
			"No opencode server configured on this Runner host.",
			"Set OPENCODE_URL (and OPENCODE_SERVER_PASSWORD when the server needs auth), then re-run model re-detection.",
		);
