async listModels({ refresh = false } = {}) {
	const runtime = await harness.modelRuntime();
	if (refresh) {
		try {
			await runtime.refresh({ allowNetwork: false });
		} catch {
			// Best-effort refresh; keep serving the stale snapshot.
