  const list = Array.isArray(visible) ? visible : [];
  if (typeof prevId === 'string' && prevId && list.some((r) => r?.runnerId === prevId)) {
    return prevId;
  }
  const fallback = list.find((r) => typeof r?.runnerId === 'string' && r.runnerId);
